// loadProcedureSourceText returns the body of a procedure exactly as
// index-bsl-fts captured it.
func loadProcedureSourceText(ctx context.Context, db *sql.DB, procedure apiProcedureDetail) (string, error) {
	var text string

	err := db.QueryRowContext(ctx, `
		SELECT f.text
		FROM bsl_fts f
		JOIN procedures p ON p.id = f.rowid
		WHERE f.rowid = ?
			AND f.start_line = p.start_line
			AND f.end_line = p.end_line
	`, procedure.ID).Scan(&text)
	if errors.Is(err, sql.ErrNoRows) {
		return loadProcedureSourceTextByPosition(ctx, db, procedure)
	}
	if err != nil {
		return "", fmt.Errorf("load procedure source text: %w", err)
	}
	return ensureTrailingNewline(text), nil
}

// loadProcedureSourceTextByPosition is the fallback for databases indexed before
// bsl_fts rows were keyed by procedure id. It costs a full scan, so it only runs
// when the rowid lookup misses.
func loadProcedureSourceTextByPosition(ctx context.Context, db *sql.DB, procedure apiProcedureDetail) (string, error) {
	var text string
	err := db.QueryRowContext(ctx, `
		SELECT text
		FROM bsl_fts
		WHERE source_file_id = ?
			AND start_line = ?
			AND end_line = ?
		LIMIT 1
	`, procedure.SourceFile.ID, procedure.StartLine, procedure.EndLine).Scan(&text)
	if errors.Is(err, sql.ErrNoRows) {
		return "", fmt.Errorf("procedure source is not indexed: id=%d (%s.%s); rerun index-bsl-fts", procedure.ID, procedure.Module, procedure.Name)
	}
	if err != nil {
		return "", fmt.Errorf("load procedure source text by position: %w", err)
	}
	return ensureTrailingNewline(text), nil
}

